function chineseSkillDescription(skill){
  const raw=String(skill.description||'').trim();
  if(/[\u3400-\u9fff]/.test(raw))return raw;
  const name=String(skill.name||'').toLowerCase();
  const exact={
    'skill-installer':'从精选列表或 GitHub 仓库安装 Codex 技能，并支持列出、验证和管理可安装技能。',
    'skill-creator':'创建或更新 Codex 技能，规范技能说明、目录结构及所需的配套资源。',
    'review-agent':'对指定代码变更执行只读、缺陷优先的审查，并返回可操作的审查结论。',
    'openai-docs':'查询 OpenAI 产品与 API 官方文档，涵盖模型、价格、配置、SDK 及使用方式。',
    'imagegen':'使用 AI 生成或编辑位图图像，适合照片、插画、纹理、精灵图和视觉素材制作。',
    'open-code-review':'使用 AI 审查 Git 代码变更，识别缺陷、风险与可改进项。',
    'open-code-review-delegate':'将开放代码审查委派给当前智能体执行，并返回结构化审查结果。',
    'plugin-creator':'创建并搭建 Codex 插件目录、清单文件及可选的插件资源。',
    'plugin-management':'发现、检查和管理插件，包括权限、依赖、连接及移除操作。',
    'browser-automation':'自动操作浏览器或桌面应用，完成页面访问、点击、填表、抓取与测试。',
    'reverse-engineer-anything':'分析本地程序、脚本、固件或网页运行逻辑，并基于实际证据说明其实现方式。',
    'documents':'创建、编辑和审阅 Word 文档，并处理批注、修订及文档格式。',
    'pdf':'读取、创建、检查和验证 PDF 文件，包括版面渲染与表单处理。',
    'spreadsheets':'创建、修改和分析电子表格，支持公式、图表、数据整理与可视化。',
    'presentations':'创建、编辑和检查演示文稿、幻灯片及相关展示内容。',
    'obsidian-cli':'通过命令行读取、创建和管理 Obsidian 笔记，并支持插件开发与调试。',
    'obsidian-markdown':'创建和编辑 Obsidian Markdown，支持双向链接、嵌入、属性和标注块。',
    'obsidian-bases':'创建和编辑 Obsidian 数据库视图，包括筛选、公式、卡片和汇总。',
    'json-canvas':'创建和编辑 Obsidian JSON Canvas，包括节点、连线、分组和布局。'
  };
  if(exact[name])return exact[name];
  const topics=[
    [/remotion/,'Remotion 视频制作'],[/caption/,'字幕处理与动画'],[/video|movie/,'视频与多媒体制作'],[/image|visual|design|logo/,'图像与视觉设计'],
    [/security|pentest|attack|exploit|threat/,'安全评估与渗透测试'],[/reverse|binary|ghidra|ida|radare|malware|forensic/,'逆向工程与安全分析'],
    [/browser|web|site/,'浏览器与网页自动化'],[/agent|planning|brainstorm|parallel|delegate/,'智能体协作与任务规划'],
    [/code|develop|test|debug|review|git|plugin/,'软件开发与质量保障'],[/document|markdown|wiki|obsidian|canvas|pdf/,'知识库与文档处理'],
    [/spreadsheet|excel/,'电子表格与数据分析'],[/presentation|slide/,'演示文稿制作'],[/cloud|k8s|database|windows|identity/,'系统与基础设施管理']
  ];
  const topic=(topics.find(([re])=>re.test(name))||[])[1]||`“${skill.name}”`;
  return `用于${topic}相关任务，提供清晰的操作流程、工具使用方法与实践指导。`;
}

