  async openSection(id){
    // Keep lake entries in sync even when optional page wrappers are hot-reloaded.
    this.containerEl.querySelectorAll('.lake-pond-entry:not(.lake-assistant-entry):not(.lake-wechat-entry),.lake-play-toolbar').forEach(node=>{node.hidden=id!=='home';});
    this.containerEl.querySelectorAll('.lake-play-panel,.lake-play-info').forEach(node=>{node.hidden=true;});
    if(id!=='home')this.pondModal?.close();
    this._wikiApexUnwatch?.();this._wechatDispose?.();this._wechatDispose=null;
    this._taskboardDispose?.();this._taskboardDispose=null;
    this._lingxiUnmount?.();this._lingxiUnmount=null;
    this.transientPointerController?.abort();this.transientPointerController=new AbortController();
    this.containerEl.children[1]?.querySelectorAll(':scope > .lake-detail, :scope > .lake-travel-stats-popover')?.forEach(x=>{x._lakeMoveCleanup?.();x.remove();});
    for(const observer of this.wikiResizeObservers||[])observer.disconnect();this.wikiResizeObservers=[];
    for(const timer of this.wikiResizeTimers?.values?.()||[])clearTimeout(timer);this.wikiResizeTimers?.clear?.();
    if(this.cubesCleanup){try{this.cubesCleanup()}catch(_){}this.cubesCleanup=null;}
    if(this.travelGlobe){try{this.travelGlobe._destructor?.()}catch(_){}this.travelGlobe=null;}this.travelMap=null;
    this.active=id; this.containerEl.querySelectorAll('.lake-nav-btn').forEach(b=>{const current=b.dataset.section===id;b.classList.toggle('is-active',current&&id!=='home');b.setAttribute('aria-current',current?'page':'false');});
    if(id==='home'){this.panel.removeClass('is-open');this.panel.empty();return;}
    this.panel.addClass('is-open'); this.panel.empty();
    if(id==='schedule') await this.renderSchedule();
    if(id==='skills') await this.renderSkills();
    if(id==='wiki') await this.renderWiki();
    if(id==='travel') await this.renderTravel();
    if(id==='tasks')await this.plugin.taskboardModule.render(this,require('obsidian'));
    if(id==='wechat')await require(path.join(this.app.vault.adapter.basePath,this.plugin.manifest.dir,'wechat-ui.js')).render(this,require('obsidian'));
    if(id==='lingxi'){const modulePath=path.join(this.app.vault.adapter.getBasePath(),this.plugin.manifest.dir,'lingxi.js');if(!this.plugin.lingxiModule){delete require('module')._cache[modulePath];this.plugin.lingxiModule=require(modulePath);}await this.plugin.lingxiModule.render(this,require('obsidian'));}
  }
