  renderCalendar(root){
    root.empty();const head=el(root,'div','lake-calendar-head');button(head,'‹',()=>{this.month=new Date(this.month.getFullYear(),this.month.getMonth()-1,1);this.renderCalendar(root)},'lake-icon-btn');
    el(head,'div','lake-calendar-title',`${this.month.getFullYear()} 年 ${this.month.getMonth()+1} 月`);button(head,'›',()=>{this.month=new Date(this.month.getFullYear(),this.month.getMonth()+1,1);this.renderCalendar(root)},'lake-icon-btn');
    const week=el(root,'div','lake-week');'一二三四五六日'.split('').forEach(x=>el(week,'div','',x));const days=el(root,'div','lake-days');
    const first=new Date(this.month);const offset=(first.getDay()+6)%7;const start=new Date(first);start.setDate(1-offset);
    for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const key=localDateKey(d);const b=button(days,String(d.getDate()),async()=>{this.date=d;this.renderCalendar(root);await this.renderDayBoard()},'lake-day');b.classList.toggle('is-other',d.getMonth()!==this.month.getMonth());b.classList.toggle('is-today',key===localDateKey());b.classList.toggle('is-selected',key===localDateKey(this.date));}
  }
  async renderDayBoard(){
    const root=this.dayBoard;root.empty();const date=localDateKey(this.date);el(root,'h3','lake-day-title',date);
    this.renderApexScheduleSummary(root);
    const compose=el(root,'div','lake-compose');const input=el(compose,'input','lake-input');input.placeholder='添加任务…';const add=async()=>{const value=input.value.trim();if(!value)return;const tasks=await this.readTasks(date);tasks.push({text:value,done:false});await this.writeTasks(date,tasks);input.value='';await this.renderDayBoard();};button(compose,'添加',add);input.addEventListener('keydown',e=>{if(e.key==='Enter')add()});
    const list=el(root,'div','lake-task-list');const tasks=await this.readTasks(date);if(!tasks.length)el(list,'div','lake-empty','当天还没有任务');
    tasks.forEach((task,index)=>{const row=el(list,'div','lake-task'+(task.done?' is-done':''));const check=el(row,'input','');check.type='checkbox';check.checked=task.done;check.addEventListener('change',async()=>{tasks[index].done=check.checked;await this.writeTasks(date,tasks);await this.renderDayBoard();});el(row,'span','lake-task-text',task.text);button(row,'编辑',async()=>{const value=prompt('编辑任务',task.text);if(value?.trim()){tasks[index].text=value.trim();await this.writeTasks(date,tasks);await this.renderDayBoard();}});button(row,'提醒',async()=>{const value=prompt('输入提醒时间（YYYY-MM-DD HH:mm）',`${date} 09:00`);if(value){tasks[index].text=task.text.replace(/ \u23f0 .+$/,'')+` \u23f0 ${value.trim()}`;await this.writeTasks(date,tasks);await this.renderDayBoard();}});button(row,'删除',async()=>{tasks.splice(index,1);await this.writeTasks(date,tasks);await this.renderDayBoard();},'lake-btn lake-danger');});
    el(root,'div','lake-subtitle','备忘录');const area=el(root,'textarea','lake-textarea');area.placeholder='记录想法…';const memoActions=el(root,'div','lake-panel-actions');button(memoActions,'保存备忘',async()=>{const text=area.value.trim();if(!text)return;await this.addMemo(text);area.value='';await this.renderDayBoard();});
    const memos=el(root,'div','lake-memo-list');(await this.readMemos()).forEach((m,i)=>{const card=el(memos,'div','lake-memo');el(card,'p','',m.text);el(card,'small','',`${m.pinned?'置顶 · ':''}${m.time}`);const ops=el(card,'div','lake-panel-actions');button(ops,m.pinned?'取消置顶':'置顶',async()=>{const all=await this.readMemos();all[i].pinned=!all[i].pinned;await this.writeMemos(all);await this.renderDayBoard();});button(ops,'保存为笔记',async()=>this.memoToNote(m));button(ops,'编辑',async()=>{const value=prompt('编辑备忘',m.text);if(value?.trim()){const all=await this.readMemos();all[i].text=value.trim();await this.writeMemos(all);await this.renderDayBoard();}});button(ops,'删除',async()=>{const all=await this.readMemos();all.splice(i,1);await this.writeMemos(all);await this.renderDayBoard();},'lake-btn lake-danger');});
  }
  async readMemos(){const f=this.app.vault.getAbstractFileByPath(normalizePath(this.plugin.settings.memoFile));if(!(f instanceof TFile))return[];return memoRowsFromText(await this.app.vault.read(f));}
  async writeMemos(items){const p=normalizePath(this.plugin.settings.memoFile);await this.ensureFolder(p.split('/').slice(0,-1).join('/'));const f=this.app.vault.getAbstractFileByPath(p),existing=f instanceof TFile?await this.app.vault.read(f):'',body=updateMemoText(existing,items);if(f instanceof TFile)await this.app.vault.modify(f,body);else await this.app.vault.create(p,body);}
