  async chooseSingleSkillFolder(input){try{let dialog;try{dialog=require('@electron/remote').dialog}catch(_){dialog=require('electron').remote?.dialog}if(typeof dialog?.showOpenDialog!=='function')throw new Error('dialog unavailable');const r=await dialog.showOpenDialog({properties:['openDirectory']});if(!r.canceled&&r.filePaths?.[0]){input.value=r.filePaths[0];input.dispatchEvent(new Event('input'));input.dispatchEvent(new Event('change'))}}catch(_){new Notice('无法打开文件夹选择器，请粘贴绝对路径')}}
  validateSkillImportPath(raw,status){const dir=path.normalize(String(raw||'').trim());const ok=fs.existsSync(path.join(dir,'SKILL.md'));status.textContent=ok?`验证通过：${dir}`:'验证失败：未找到 SKILL.md';status.classList.toggle('is-ok',ok);status.classList.toggle('is-error',!ok);return ok}
