  ensureWikiApex(){
    if(this.wikiApex)return this.wikiApex;
    const apex=this.app.plugins.plugins['apex-dashboard'],factory=this.app.viewRegistry.viewByType['apex-dashboard-view'];
    if(!apex||!factory)throw Error('请保持 Apex Dashboard 启用，以使用原版分区、文件夹和模板功能。');
    const owner=this,engine=factory(this.leaf),facade=Object.create(apex),baseline=JSON.parse(JSON.stringify(apex.settings));
    facade.settings={...baseline,...this.plugin.settings.wikiApexSettings,layoutMode:'side'};
    facade.saveSettings=async()=>{const overrides={};for(const [key,value]of Object.entries(facade.settings))if(key!=='dashboardFile'&&JSON.stringify(value)!==JSON.stringify(baseline[key]))overrides[key]=value;owner.plugin.settings.wikiApexSettings=overrides;await owner.plugin.saveSettings();};
    facade.refreshAllDashboards=()=>engine.render(engine.data);facade.getActiveDashboardView=()=>engine;
    engine.plugin=facade;engine.sync.updateSettings(facade.settings);
    engine.sync.data=JSON.parse(JSON.stringify(this.plugin.settings.wikiApexData||{columns:[],quickActions:[],banner:{title:'Wiki 知识库'},layout:'side'}));engine.data=engine.sync.data;
    const cleanup=()=>{for(const f of engine.cleanupFns.splice(0))f();for(const f of engine.dndCleanupFns.splice(0))f();};
    engine.render=data=>{engine.data=data;const root=engine.containerEl.children[1];if(!root?.isConnected)return;cleanup();root.empty();root.classList.add('apex-dashboard-root');root.setAttribute('data-theme',facade.settings.stylePreset||'mono');root.setAttribute('data-layout','side');const wrapper=root.createDiv({cls:'dashboard-kanban-wrapper'}),board=wrapper.createDiv({cls:'dashboard-kanban'});for(const column of data.columns){const placeholder=board.createDiv();placeholder.dataset.column=column.name;}engine.attachBoardEventDelegation(board);for(const column of data.columns)engine.refreshSectionInPlace(column.name);if(!data.columns.length)board.createDiv({cls:'lake-empty',text:'点击顶部“新建分区”或“新建文件夹”，使用 Apex 原版配置和模板。'});};
    engine.handleDataUpdate=data=>{engine.data=data;engine.suppressNextRender=false;engine.render(data);};
    engine.sync.writeToDisk=async function(quiet=false){if(!this.data)return;const snapshot=JSON.parse(JSON.stringify(this.data));this.writeQueue=this.writeQueue.catch(()=>{}).then(async()=>{owner.plugin.settings.wikiApexData=snapshot;await owner.plugin.saveSettings();});await this.writeQueue;if(!quiet)this.notifyCallbacks('local');};
    // Wiki sections persist in the workbench; Apex's original dashboard file is never initialized by this adapter.
    engine.sync.refresh=async()=>{engine.handleDataUpdate(engine.sync.data);};engine.sync.reloadFromDisk=engine.sync.refresh;
    this.wikiApex=engine;
    this.register(()=>{cleanup();engine.unregisterVaultListeners();engine.sync.destroy();engine.containerEl.remove();this.wikiApex=null;});
    return engine;
  }
  mountWikiApex(body){
    const host=el(body,'div','lake-wiki-apex');let engine;try{engine=this.ensureWikiApex();}catch(error){el(host,'p','lake-empty',error.message);return;}
    host.append(engine.containerEl);engine.containerEl.classList.add('lake-wiki-apex-view');engine.render(engine.sync.data);
    this._wikiApexUnwatch?.();const refs=[];let timer;const refresh=()=>{clearTimeout(timer);timer=setTimeout(()=>{if(host.isConnected)engine.render(engine.sync.data);},350);};for(const name of ['create','modify','delete','rename'])refs.push(this.app.vault.on(name,refresh));refs.push(this.app.metadataCache.on('changed',refresh));
    this._wikiApexUnwatch=()=>{clearTimeout(timer);for(let i=0;i<refs.length-1;i++)this.app.vault.offref(refs[i]);this.app.metadataCache.offref(refs.at(-1));this._wikiApexUnwatch=null;};this.register(()=>this._wikiApexUnwatch?.());
  }
  openWikiApexSection(type){
    try{const engine=this.ensureWikiApex();engine.openAddSectionModalInner();if(type){const dialogs=[...document.querySelectorAll('.dashboard-library-config-modal')],dialog=dialogs.at(-1);dialog?.querySelector('[data-type='+type+']')?.click();}}catch(error){new Notice(error.message);}
  }
