class LakeSettings extends PluginSettingTab {
  constructor(app,plugin){super(app,plugin);this.plugin=plugin;}
  display(){const {containerEl}=this;containerEl.empty();containerEl.createEl('h2',{text:'湖面设置'});
    new Setting(containerEl).setName('一次性导入 Apex Dashboard').setDesc('合并技能目录与分组、Wiki 导航、待办、倒计时和纪念日；不修改 Apex 原数据。').addButton(x=>x.setButtonText(this.plugin.settings.apexImport?'重新导入':'开始导入').setCta().onClick(async()=>{try{const result=await this.plugin.importApex();new Notice(`Apex 导入完成：${result.tasks} 个待办，${result.links} 个 Wiki 链接`);this.display();}catch(e){new Notice(`Apex 导入失败：${e.message}`);}}));
    new Setting(containerEl).setName('日程目录').setDesc('每天任务的 Markdown 存放目录').addText(x=>x.setValue(this.plugin.settings.scheduleFolder).onChange(async v=>{this.plugin.settings.scheduleFolder=v.trim();await this.plugin.saveSettings()}));
    new Setting(containerEl).setName('备忘录文件').addText(x=>x.setValue(this.plugin.settings.memoFile).onChange(async v=>{this.plugin.settings.memoFile=v.trim();await this.plugin.saveSettings()}));
    new Setting(containerEl).setName('技能目录').setDesc('多个绝对路径使用英文逗号分隔').addTextArea(x=>x.setValue(this.plugin.settings.skillSourceFolders).onChange(async v=>{this.plugin.settings.skillSourceFolders=v;await this.plugin.saveSettings()}));
  }
}

